package com.github.dappermickie.odablock.ui;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.awt.image.RescaleOp;
import javax.swing.ImageIcon;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

@Slf4j
final class ToolbarIcons
{
	private static final float HOVER_BRIGHTNESS = 1.2f;

	static final ImageIcon PLUS = loadIcon("new.png");
	static final ImageIcon PLUS_HOVER = brighten(PLUS);

	static final ImageIcon EXPORT = loadIcon("export.png");
	static final ImageIcon EXPORT_HOVER = brighten(EXPORT);

	static final ImageIcon IMPORT = loadIcon("import.png");
	static final ImageIcon IMPORT_HOVER = brighten(IMPORT);

	static final ImageIcon CLOSE = loadIcon("close.png");
	static final ImageIcon CLOSE_HOVER = brighten(CLOSE);

	static final ImageIcon BACK = loadIcon("back.png");
	static final ImageIcon BACK_HOVER = brighten(BACK);

	static final ImageIcon TRASH = loadIcon("trash.png");
	static final ImageIcon TRASH_HOVER = brighten(TRASH);

	static final ImageIcon PLAY = loadIcon("play.png");
	static final ImageIcon PLAY_HOVER = brighten(PLAY);

	static final ImageIcon CHECK = loadIcon("check.png");

	private ToolbarIcons()
	{
	}

	private static ImageIcon loadIcon(String resourceName)
	{
		try
		{
			BufferedImage image = ImageUtil.loadImageResource(ToolbarIcons.class, resourceName);
			if (image != null)
			{
				return new ImageIcon(image);
			}
			log.warn("Toolbar icon resource '{}' could not be loaded.", resourceName);
		}
		catch (Exception exception)
		{
			log.warn("Toolbar icon resource '{}' is missing.", resourceName, exception);
		}
		return new ImageIcon(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB));
	}

	private static ImageIcon brighten(ImageIcon source)
	{
		if (source == null || source.getIconWidth() <= 1 || source.getIconHeight() <= 1)
		{
			return source;
		}
		try
		{
			BufferedImage src = toBufferedImage(source.getImage(),
				source.getIconWidth(), source.getIconHeight());
			RescaleOp op = new RescaleOp(HOVER_BRIGHTNESS, 0, null);
			BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
			op.filter(src, out);
			return new ImageIcon(out);
		}
		catch (Exception exception)
		{
			log.debug("Failed to derive hover icon; reusing source.", exception);
			return source;
		}
	}

	private static BufferedImage toBufferedImage(Image image, int width, int height)
	{
		BufferedImage buffered = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = buffered.createGraphics();
		graphics.drawImage(image, 0, 0, null);
		graphics.dispose();
		return buffered;
	}
}

package com.github.dappermickie.odablock.ui;

import com.github.dappermickie.odablock.overrides.SoundOverrideAction;
import com.github.dappermickie.odablock.overrides.SoundOverrideService;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.datatransfer.StringSelection;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.util.SwingUtil;

class OverridesListView extends JPanel
{
	private final SoundOverrideService soundOverrideService;
	private final Runnable onAddOverrideRequested;
	private final Consumer<SoundOverrideAction> onEditOverrideRequested;

	private final VerticalScrollPane scrollPane;
	private final VerticalScrollPane.ScrollableContainer rowsContainer;
	private final PluginErrorPanel emptyPanel;
	private final JLabel toastLabel;
	private final Timer toastTimer;

	OverridesListView(
		SoundOverrideService soundOverrideService,
		Runnable onAddOverrideRequested,
		Consumer<SoundOverrideAction> onEditOverrideRequested)
	{
		this.soundOverrideService = soundOverrideService;
		this.onAddOverrideRequested = onAddOverrideRequested;
		this.onEditOverrideRequested = onEditOverrideRequested;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		this.scrollPane = new VerticalScrollPane();
		this.rowsContainer = scrollPane.getContainer();
		this.emptyPanel = new PluginErrorPanel();
		this.toastLabel = new JLabel();
		this.toastTimer = new Timer(1800, event -> toastLabel.setVisible(false));
		this.toastTimer.setRepeats(false);

		emptyPanel.setContent(
			"No overrides yet",
			"Click the + button above to create your first override."
		);

		add(buildHeader(), BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);

		refresh();
	}

	void refresh()
	{
		SwingUtilities.invokeLater(() -> rebuildRows(false));
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(10, 10, 8, 10));

		JLabel titleLabel = new JLabel("Odablock Overrides");
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);

		JButton exportButton = new JButton();
		stylizeIconButton(exportButton, ToolbarIcons.EXPORT, ToolbarIcons.EXPORT_HOVER);
		exportButton.setToolTipText("Copy overrides JSON to clipboard");
		exportButton.addActionListener(event -> exportToClipboard());

		JButton importButton = new JButton();
		stylizeIconButton(importButton, ToolbarIcons.IMPORT, ToolbarIcons.IMPORT_HOVER);
		importButton.setToolTipText("Import overrides from JSON");
		importButton.addActionListener(event -> openImportDialog());

		JButton addButton = new JButton();
		stylizeIconButton(addButton, ToolbarIcons.PLUS, ToolbarIcons.PLUS_HOVER);
		addButton.setToolTipText("Add override");
		addButton.addActionListener(event -> onAddOverrideRequested.run());

		JPanel toolbar = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		toolbar.setOpaque(false);
		toolbar.add(exportButton);
		toolbar.add(importButton);
		toolbar.add(addButton);

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		titleRow.add(titleLabel, BorderLayout.WEST);
		titleRow.add(toolbar, BorderLayout.EAST);

		toastLabel.setForeground(new Color(95, 175, 95));
		toastLabel.setVisible(false);
		toastLabel.setBorder(new EmptyBorder(6, 2, 0, 0));

		header.add(titleRow);
		header.add(toastLabel);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		return header;
	}

	private void stylizeIconButton(JButton button, javax.swing.ImageIcon icon, javax.swing.ImageIcon rolloverIcon)
	{
		button.setIcon(icon);
		button.setRolloverIcon(rolloverIcon);
		button.setFocusPainted(false);
		button.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		SwingUtil.removeButtonDecorations(button);
		button.setBackground(ColorScheme.DARK_GRAY_COLOR);
	}

	private void rebuildRows(boolean resetScroll)
	{
		int previousScroll = scrollPane.getScrollValue();

		SwingUtil.fastRemoveAll(rowsContainer);

		Map<SoundOverrideAction, Integer> activeOverrides = new LinkedHashMap<>();
		for (SoundOverrideAction action : SoundOverrideAction.values())
		{
			int count = soundOverrideService.getOverrideFileNames(action).size();
			if (count > 0)
			{
				activeOverrides.put(action, count);
			}
		}

		if (activeOverrides.isEmpty())
		{
			JPanel emptyWrapper = new JPanel(new BorderLayout());
			emptyWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
			emptyWrapper.setBorder(new EmptyBorder(20, 8, 20, 8));
			emptyWrapper.add(emptyPanel, BorderLayout.CENTER);
			rowsContainer.add(emptyWrapper);
		}
		else
		{
			for (Map.Entry<SoundOverrideAction, Integer> entry : activeOverrides.entrySet())
			{
				OverrideRow row = new OverrideRow(
					entry.getKey(),
					entry.getValue(),
					onEditOverrideRequested,
					this::deleteOverride
				);
				JPanel margin = new JPanel(new BorderLayout());
				margin.setBackground(ColorScheme.DARK_GRAY_COLOR);
				margin.setBorder(new EmptyBorder(2, 8, 2, 8));
				margin.add(row, BorderLayout.CENTER);
				margin.setMaximumSize(new Dimension(Integer.MAX_VALUE, margin.getPreferredSize().height));
				rowsContainer.add(margin);
			}
		}

		rowsContainer.add(Box.createVerticalGlue());
		rowsContainer.revalidate();
		rowsContainer.repaint();

		if (resetScroll)
		{
			scrollPane.scrollToTop();
		}
		else
		{
			// Restore scroll AFTER layout has settled so the scrollbar's max
			// has been recomputed against the new contents.
			SwingUtilities.invokeLater(() -> scrollPane.setScrollValue(previousScroll));
		}
	}

	private void deleteOverride(SoundOverrideAction action)
	{
		soundOverrideService.clearOverrideFileNames(action);
		refresh();
	}

	private void exportToClipboard()
	{
		String json = soundOverrideService.exportOverridesAsJson();
		StringSelection selection = new StringSelection(json);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);
		showToast("Copied overrides JSON to clipboard");
	}

	private void openImportDialog()
	{
		Window owner = SwingUtilities.getWindowAncestor(this);
		ImportOverridesDialog dialog = new ImportOverridesDialog(
			owner,
			soundOverrideService,
			summary -> {
				refresh();
				showToast(summary);
			}
		);
		dialog.setVisible(true);
	}

	private void showToast(String message)
	{
		toastLabel.setText(message);
		toastLabel.setVisible(true);
		toastTimer.restart();
	}
}

package com.github.dappermickie.odablock.ui;

import com.github.dappermickie.odablock.overrides.SoundOverrideAction;
import com.github.dappermickie.odablock.overrides.SoundOverrideService;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.CardLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.util.SwingUtil;

class ActionPickerView extends JPanel
{
	private static final String CARD_RESULTS = "RESULTS";
	private static final String CARD_INFO = "INFO";

	private final SoundOverrideService soundOverrideService;
	private final Consumer<SoundOverrideAction> onActionSelected;
	private final Runnable onCancel;

	private final IconTextField searchField;
	private final VerticalScrollPane scrollPane;
	private final VerticalScrollPane.ScrollableContainer rowsContainer;
	private final CardLayout cardLayout;
	private final JPanel cardPanel;
	private final PluginErrorPanel infoPanel;

	ActionPickerView(
		SoundOverrideService soundOverrideService,
		Consumer<SoundOverrideAction> onActionSelected,
		Runnable onCancel)
	{
		this.soundOverrideService = soundOverrideService;
		this.onActionSelected = onActionSelected;
		this.onCancel = onCancel;

		this.searchField = new IconTextField();
		this.scrollPane = new VerticalScrollPane();
		this.rowsContainer = scrollPane.getContainer();
		this.cardLayout = new CardLayout();
		this.cardPanel = new JPanel(cardLayout);
		this.infoPanel = new PluginErrorPanel();

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		configureSearchField();
		buildCardPanel();

		add(buildHeader(), BorderLayout.NORTH);
		add(cardPanel, BorderLayout.CENTER);
	}

	void refresh()
	{
		searchField.setText("");
		SwingUtilities.invokeLater(() -> {
			rebuildRows();
			searchField.requestFocusInWindow();
		});
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(10, 10, 6, 10));

		JLabel titleLabel = new JLabel("New Override");
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);

		JButton closeButton = new JButton();
		closeButton.setIcon(ToolbarIcons.CLOSE);
		closeButton.setRolloverIcon(ToolbarIcons.CLOSE_HOVER);
		closeButton.setToolTipText("Cancel");
		closeButton.setFocusPainted(false);
		SwingUtil.removeButtonDecorations(closeButton);
		closeButton.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		closeButton.setBackground(ColorScheme.DARK_GRAY_COLOR);
		closeButton.addActionListener(event -> {
			if (onCancel != null)
			{
				onCancel.run();
			}
		});

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		titleRow.add(titleLabel, BorderLayout.WEST);
		titleRow.add(closeButton, BorderLayout.EAST);

		JLabel subtitle = new JLabel("Choose which action to override");
		subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		subtitle.setBorder(new EmptyBorder(4, 0, 8, 0));

		header.add(titleRow);
		header.add(subtitle);
		header.add(searchField);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		return header;
	}

	private void configureSearchField()
	{
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setPreferredSize(new Dimension(100, 28));
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.addClearListener(this::rebuildRows);
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuildRows();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuildRows();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuildRows();
			}
		});
	}

	private void buildCardPanel()
	{
		cardPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel infoWrapper = new JPanel(new BorderLayout());
		infoWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		infoWrapper.setBorder(new EmptyBorder(20, 8, 20, 8));
		infoPanel.setContent("No matches", "No actions match your search.");
		infoWrapper.add(infoPanel, BorderLayout.NORTH);

		cardPanel.add(scrollPane, CARD_RESULTS);
		cardPanel.add(infoWrapper, CARD_INFO);
		cardLayout.show(cardPanel, CARD_RESULTS);
	}

	private void rebuildRows()
	{
		SwingUtil.fastRemoveAll(rowsContainer);

		String query = searchField.getText() == null ? "" : searchField.getText().trim().toLowerCase(Locale.ENGLISH);
		int matchCount = 0;
		for (SoundOverrideAction action : SoundOverrideAction.values())
		{
			if (!query.isEmpty() && !action.getDisplayName().toLowerCase(Locale.ENGLISH).contains(query))
			{
				continue;
			}

			boolean alreadyOverridden = !soundOverrideService.getOverrideFileNames(action).isEmpty();
			JPanel row = createRow(action, alreadyOverridden);

			JPanel margin = new JPanel(new BorderLayout());
			margin.setBackground(ColorScheme.DARK_GRAY_COLOR);
			margin.setBorder(new EmptyBorder(2, 8, 2, 8));
			margin.add(row, BorderLayout.CENTER);
			margin.setMaximumSize(new Dimension(Integer.MAX_VALUE, margin.getPreferredSize().height));
			rowsContainer.add(margin);
			matchCount++;
		}

		if (matchCount == 0)
		{
			cardLayout.show(cardPanel, CARD_INFO);
		}
		else
		{
			rowsContainer.add(Box.createVerticalGlue());
			cardLayout.show(cardPanel, CARD_RESULTS);
		}

		rowsContainer.revalidate();
		rowsContainer.repaint();
		scrollPane.scrollToTop();
	}

	private JPanel createRow(SoundOverrideAction action, boolean alreadyOverridden)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		Color accent = alreadyOverridden ? new Color(95, 175, 95) : ColorScheme.BORDER_COLOR;
		row.setBorder(new CompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			new EmptyBorder(8, 10, 8, 10)
		));

		JLabel nameLabel = new JLabel(action.getDisplayName());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeFont());

		row.add(nameLabel, BorderLayout.CENTER);

		if (alreadyOverridden)
		{
			JLabel statusLabel = new JLabel("override set");
			statusLabel.setForeground(new Color(95, 175, 95));
			statusLabel.setFont(FontManager.getRunescapeSmallFont());
			row.add(statusLabel, BorderLayout.EAST);
		}

		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText(alreadyOverridden
			? "Edit existing override for " + action.getDisplayName()
			: "Create override for " + action.getDisplayName());

		final Color hoverBackground = ColorScheme.DARK_GRAY_HOVER_COLOR;
		final Color normalBackground = ColorScheme.DARKER_GRAY_COLOR;
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				row.setBackground(hoverBackground);
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				row.setBackground(normalBackground);
			}

			@Override
			public void mouseReleased(MouseEvent event)
			{
				if (event.getButton() == MouseEvent.BUTTON1 && onActionSelected != null)
				{
					onActionSelected.accept(action);
				}
			}
		});
